import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.beans.factory.annotation.Autowired; import com.ejemplo.tienda.catalogo.CatalogApi; import static org.junit.jupiter.api.Assertions.*;
